INSERT INTO `query_logs` VALUES
(1,0,'1','SELECT u.`id_utente` AS `id`, u.`nome` AS `nome`, u.`cognome` AS `cognome`, u.`email` AS `email`, u.`telefono` AS `telefono`, u.`attivo` AS `attivo`, u.`id_tenant` AS `tenant`, u.`id_master` AS `id_master`, u.`id_profilo` AS `id_profilo`, u.`privacy_accepted` AS `privacy_accepted`, u.`email_status` AS `email_status`, u.`email_proof_token` AS `email_proof_token`, u.`email_proof_token_expires_at` AS `email_proof_token_expires_at`, u.`password_reset_token` AS `password_reset_token`, u.`password_reset_token_expires_at` AS `password_reset_token_expires_at` FROM `utenti` AS u WHERE `u`.`id_utente` = ? LIMIT 1 OFFSET 0',1,'2026-05-08 15:03:38'),
(2,0,'1','SELECT u.`id_utente` AS `id`, u.`nome` AS `nome`, u.`cognome` AS `cognome`, u.`email` AS `email`, u.`telefono` AS `telefono`, u.`attivo` AS `attivo`, u.`id_tenant` AS `tenant`, u.`id_master` AS `id_master`, u.`id_profilo` AS `id_profilo`, u.`privacy_accepted` AS `privacy_accepted`, u.`email_status` AS `email_status`, u.`email_proof_token` AS `email_proof_token`, u.`email_proof_token_expires_at` AS `email_proof_token_expires_at`, u.`password_reset_token` AS `password_reset_token`, u.`password_reset_token_expires_at` AS `password_reset_token_expires_at` FROM `utenti` AS u WHERE `u`.`id_utente` = ? LIMIT 1 OFFSET 0',1,'2026-05-08 15:03:38'),
(3,1,'1','SELECT e.`id_evento` AS `id`, e.`id_comune` AS `id_comune`, e.`titolo` AS `titolo`, e.`descrizione` AS `descrizione`, e.`data_inizio` AS `data_inizio`, e.`data_fine` AS `data_fine`, e.`codice_menu` AS `codice_menu`, e.`logo` AS `logo`, e.`id_host` AS `id_host`, e.`ordinamento` AS `ordinamento`, c.`comune` AS `comune`, a.`allegato` AS `allegato`, a.`tipologia_allegato` AS `tipologia_allegato` FROM `eventi` AS e LEFT JOIN `comuni` AS c ON e.id_comune = c.id_comune LEFT JOIN `allegati` AS a ON e.id_evento = a.id_evento WHERE `e`.`id_host` = ? ORDER BY e.data_inizio ASC',1,'2026-05-08 15:03:38');
/*!40000 ALTER TABLE `query_logs` ENABLE KEYS */;
UNLOCK TABLES;

